import { createHash, randomBytes } from 'node:crypto';

// Group constants
export const P = 0xc135f37294f32354bf0f6657726b3a61a5c4b31f0de34bf8465832f1d7a95637n;
export const Q = 0x609af9b94a7991aa5f87b32bb9359d30d2e2598f86f1a5fc232c1978ebd4ab1bn;
export const G = 4n;

/**
 * Compute challenge as SHA-256 hash modulo Q
 * @param {bigint} t1 - First element
 * @param {bigint} t2 - Second element
 * @returns {bigint} challenge value in [0, Q)
 */
export function challenge(t1, t2) {
  const t1Hex = t1.toString(16);
  const t2Hex = t2.toString(16);
  const message = t1Hex + '|' + t2Hex;

  const hash = createHash('sha256');
  hash.update(message);
  const digest = hash.digest('hex');

  return BigInt('0x' + digest) % Q;
}

/**
 * Generate a random integer in [0, Q)
 * @returns {bigint} random value
 */
function randomScalar() {
  let r;
  const maxBytes = (Q.toString(2).length + 7) >> 3;
  do {
    r = BigInt('0x' + randomBytes(maxBytes).toString('hex'));
  } while (r >= Q);
  return r;
}

/**
 * Modular exponentiation: base^exp mod modulus
 */
const powmod = (base, exp, mod) => {
  base = base % mod;
  let result = 1n;
  while (exp > 0n) {
    if (exp % 2n === 1n) result = (result * base) % mod;
    base = (base * base) % mod;
    exp = exp >> 1n;
  }
  return result;
};

/**
 * Extended GCD for modular inverse
 */
function extgcd(a, b) {
  if (b === 0n) return [a, 1n, 0n];
  const [g, x1, y1] = extgcd(b, a % b);
  const x = y1;
  const y = x1 - (a / b) * y1;
  return [g, x, y];
}

/**
 * Modular inverse: a^-1 mod m
 */
function modinv(a, m) {
  const [g, x] = extgcd(a % m, m);
  if (g !== 1n) throw new Error('Modular inverse does not exist');
  return (x % m + m) % m;
}

/**
 * Prove knowledge of discrete log for one of two bases
 * The prover knows x such that y_which = g^x (mod p)
 * Returns a proof that reveals nothing about which
 * 
 * @param {bigint} x - The discrete log (of y1 if which=1, of y2 if which=2)
 * @param {number} which - Which statement (1 or 2) is the true one
 * @param {bigint} y1 - First public value (g^x1 mod p)
 * @param {bigint} y2 - Second public value (g^x2 mod p)
 * @returns {object} proof {t1, t2, c1, c2, s1, s2}
 */
export function proveOr(x, which, y1, y2) {
  if (which !== 1 && which !== 2) {
    throw new Error('which must be 1 or 2');
  }

  // For the true statement (which), we commit honestly
  const w_true = randomScalar();
  const t_true = powmod(G, w_true, P);

  // For the false statement, simulate a proof
  const c_false = randomScalar();
  const s_false = randomScalar();

  const y_false = which === 1 ? y2 : y1;
  // Compute t_false such that the verification equation holds:
  // g^s_false = t_false * y_false^c_false (mod p)
  // So: t_false = g^s_false / y_false^c_false (mod p)
  const y_false_c = powmod(y_false, c_false, P);
  const inv_y_false_c = modinv(y_false_c, P);
  const t_false = (powmod(G, s_false, P) * inv_y_false_c) % P;

  // Compute the challenge on both commitments
  const t1 = which === 1 ? t_true : t_false;
  const t2 = which === 1 ? t_false : t_true;
  const c = challenge(t1, t2);

  // Derive the challenge for the true statement
  const c_true = (c - c_false + Q) % Q;
  const s_true = (w_true + c_true * x) % Q;

  // Construct the proof
  const proof = {
    t1,
    t2,
    c1: which === 1 ? c_true : c_false,
    c2: which === 1 ? c_false : c_true,
    s1: which === 1 ? s_true : s_false,
    s2: which === 1 ? s_false : s_true
  };

  return proof;
}

/**
 * Verify a zero-knowledge OR-proof
 * 
 * @param {bigint} y1 - First public value
 * @param {bigint} y2 - Second public value
 * @param {object} proof - The proof object {t1, t2, c1, c2, s1, s2}
 * @returns {boolean} true if the proof is valid
 */
export function verifyOr(y1, y2, proof) {
  const { t1, t2, c1, c2, s1, s2 } = proof;

  // Check that c1 + c2 = challenge(t1, t2) (mod q)
  const c = challenge(t1, t2);
  const c_sum = (c1 + c2) % Q;
  if (c_sum !== c) {
    return false;
  }

  // Check g^s1 = t1 * y1^c1 (mod p)
  const lhs1 = powmod(G, s1, P);
  const rhs1 = (t1 * powmod(y1, c1, P)) % P;
  if (lhs1 !== rhs1) {
    return false;
  }

  // Check g^s2 = t2 * y2^c2 (mod p)
  const lhs2 = powmod(G, s2, P);
  const rhs2 = (t2 * powmod(y2, c2, P)) % P;
  if (lhs2 !== rhs2) {
    return false;
  }

  return true;
}

